package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BZip2CompressorInputStream_read_TriageGen2Test {

    @Test
    public void testRead_OffsNegative() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        try (BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is)) {
            assertThrows(IndexOutOfBoundsException.class, () -> {
                bzIn.read(new byte[10], -1, 5);
            });
        }
    }

    @Test
    public void testRead_LenNegative() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        try (BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is)) {
            assertThrows(IndexOutOfBoundsException.class, () -> {
                bzIn.read(new byte[10], 0, -1);
            });
        }
    }

    @Test
    public void testRead_OutOfBounds() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        try (BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is)) {
            assertThrows(IndexOutOfBoundsException.class, () -> {
                bzIn.read(new byte[10], 5, 6);
            });
        }
    }

    @Test
    public void testRead_StreamClosed() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);
        bzIn.close();
        assertThrows(IOException.class, () -> {
            bzIn.read(new byte[10], 0, 5);
        });
    }

    @Test
    public void testRead_LenZero() throws IOException {
        // Create a valid BZip2 stream (minimal)
        byte[] bzip2Data = new byte[] {
            (byte) 0x42, (byte) 0x5A, (byte) 0x68, (byte) 0x32, (byte) 0x31, (byte) 0x41, (byte) 0x58, (byte) 0x20, 
            (byte) 0x59, (byte) 0x5a, (byte) 0x53, (byte) 0x20, (byte) 0x41, (byte) 0x42, (byte) 0x50, (byte) 0x20, 
            (byte) 0x30, (byte) 0x34, (byte) 0x35, (byte) 0x36, (byte) 0x37, (byte) 0x38, (byte) 0x39, (byte) 0x00
        };
        // Use a mock to bypass actual decompression logic complexity while testing the read structure
        InputStream mockIs = mock(InputStream.class);
        when(mockIs.read()).thenReturn(-1); 

        // We need to trigger the 'in == null' check or the loop. 
        // Since we cannot easily inject into the private 'in' field without reflection, 
        // we use a real stream or a mock that simulates the behavior.

        // Testing the len == 0 branch
        try (BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(new ByteArrayInputStream(bzip2Data))) {
            int result = bzIn.read(new byte[10], 0, 0);
            assertEquals(0, result);
        }
    }

    @Test
    public void testRead_EOF() throws IOException {
        // Create a mock to control read0() via the underlying stream
        // Note: BZip2CompressorInputStream calls read0() which calls in.read()
        InputStream mockIs = mock(InputStream.class);
        when(mockIs.read(any(byte[].class), anyInt(), anyInt())).thenReturn(-1);

        try (BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(mockIs)) {
            byte[] dest = new byte[10];
            int result = bzIn.read(dest, 0, 5);
            assertEquals(-1, result);
        }
    }

    @Test
    public void testRead_Success() throws IOException {
        // To test the loop and successful reads, we provide a valid compressed stream
        // Using a small real BZip2 payload
        byte[] bzip2Data = new byte[] {
            (byte) 0x42, (byte) 0x5A, (byte) 0x68, (byte) 0x32, (byte) 0x31, (byte) 0x41, (byte) 0x58, (byte) 0x20, 
            (byte) 0x59, (byte) 0x5a, (byte) 0x53, (byte) 0x20, (byte) 0x41, (byte) 0x42, (byte) 0x50, (byte) 0x20, 
            (byte) 0x30, (byte) 0x34, (byte) 0x35, (byte) 0x36, (byte) 0x37, (byte) 0x38, (byte) 0x39, (byte) 0x00 
        };
        // Because actual BZip2 decompression is complex, we focus on the logic of the 'read' method 
        // by mocking the InputStream to return valid bytes.
        InputStream mockIs = mock(InputStream.class);
        // Simulate reading one byte then EOF
        when(mockIs.read(any(byte[].class), anyInt(), anyInt())).thenAnswer(invocation -> {
            byte[] buf = invocation.getArgument(0);
            int off = invocation.getArgument(1);
            int len = invocation.getArgument(2);
            buf[off] = (byte) 'A';
            return 1;
        }).thenReturn(-1);

        try (BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(mockIs)) {
            byte[] dest = new byte[10];
            int result = bzIn.read(dest, 0, 5);
            // Since the loop condition is destOffs <= hi, and read0 returns data, 
            // it will read until EOF.
            // The logic `destOffs <= hi` in the provided code is slightly unusual (usually < hi)
            // but we test according to the provided implementation.
            if (result > 0) {
                assertEquals('A', dest[0]);
            }
        }
    }

    // Helper to support mockito any() for primitive/array arguments in Java 11
    private static <T> T any(Class<T> type) {
        return org.mockito.ArgumentMatchers.any(type);
    }
    private static int anyInt() {
        return org.mockito.ArgumentMatchers.anyInt();
    }
}
